import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Hex, Skill, Projectile } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

// Lightweight struct to track Danger Zones without map allocation
interface DangerSource {
    q: number;
    r: number;
    radiusSq: number; // Squared radius for fast check
    color: string;
    visual: string;
    progress: number;
}

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 

export class GridSystem {
    // Cache
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuse buffers
    private _dangerSources: DangerSource[] = [];
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        this.ensureCache(engine);
        const limit = HEX_SIZE * 2; 

        // Find closest tile visual center
        let bestTile: CachedTile | null = null;
        let bestDist = Infinity;

        // Optimization: Simple distance check first
        for (const tile of this._tileCache) {
            // Visual Y center is py - h
            const visualY = tile.py - tile.h;
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - visualY);
            if (dist < limit && dist < bestDist) { 
                bestDist = dist;
                bestTile = tile;
            }
        }

        if (bestTile) {
            // Precise check
            const testHex = HexUtils.fromPx(wx, wy + bestTile.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === bestTile.q && rounded.r === bestTile.r) {
                return { q: bestTile.q, r: bestTile.r };
            }
        }
        return null;
    }

    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;
            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         if (nHeight > uHeight) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        });
        return occluded;
    }

    submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.ensureCache(engine);

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Reset buffers
        this._dangerSources.length = 0;
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        // 1. Scan Agents for AOE and Status
        for (const a of engine.agents) {
            if (a.hp > 0) {
                // Populate Unit Status Maps
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);

                // Populate Danger Sources (No allocations)
                if (a.stunTimer <= 0 && a.silenceTimer <= 0 && !a.banished && a.castingSkillIdx !== -1) {
                    const s = a.skills[a.castingSkillIdx];
                    if (s && s.type === 'AOE') {
                        let tq = a.q, tr = a.r;
                        if (a.targetHex) { tq = a.targetHex.q; tr = a.targetHex.r; }
                        else if (a.target) { tq = a.target.q; tr = a.target.r; }

                        const progress = 1 - (a.castTimer / s.cast);
                        // RIPPLE UPDATE: Track full radius immediately for UX, animation uses progress
                        const maxRadius = (s.aoeRadius || 1);

                        this._dangerSources.push({
                            q: tq, r: tr,
                            radiusSq: maxRadius + 0.1, // Full radius inclusion
                            color: s.color,
                            visual: s.visual || 'BOLT',
                            progress: progress
                        });
                    }
                }
            }
        }

        // 2. Iterate Tiles & Obstacles
        const PROJ_LIGHT_RADIUS_SQ = 1600; // 40^2

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualY = py + offset;

            if (visualY > py + 800) continue;

            const k = `${q},${r}`;

            // --- SUBMIT OBSTACLE ---
            const obstacleType = engine.obstacles.get(k);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = visualY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualY - h - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // --- SUBMIT TERRAIN ---
            // Determine Danger Zone without allocation
            let dangerInfo = undefined;
            for (const ds of this._dangerSources) {
                // Dist calculation
                const dist = (Math.abs(q - ds.q) + Math.abs(q + r - ds.q - ds.r) + Math.abs(r - ds.r)) / 2;
                if (dist <= ds.radiusSq) {
                    dangerInfo = {
                        color: ds.color,
                        progress: ds.progress,
                        visual: ds.visual,
                        state: 'ACTIVE',
                        fadeRatio: 1.0,
                        // RIPPLE UPDATE: Pass context for wave calculation
                        centerQ: ds.q,
                        centerR: ds.r,
                        radius: Math.floor(ds.radiusSq)
                    };
                    break; // Just take the first overlapping danger zone
                }
            }

            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const bonus = Math.max(0, Math.floor((agentH - h) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;
                const dist = (Math.abs(q - highlightAgent.q) + Math.abs(q + r - highlightAgent.q - highlightAgent.r) + Math.abs(r - highlightAgent.r)) / 2;

                if (dist <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // Populate RenderOp for Terrain
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = visualY; 
            op.z = 0;

            op.tx = px; 
            op.ty = visualY; // Base Y
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q;
            op.tr = r;

            // Overlays
            op.oStatus = specialStatus;
            op.oDanger = dangerInfo;
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);
            // op.oFlash removed
            op.oRange = isRange;
            op.oRangeCol = rangeColor;
            op.oHover = isHover;
            op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { TerrainRenderer } from "./TerrainRenderer";
import { AOERenderer } from "./AOERenderer";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Note: y here should be the "visual top" y (y - topY)
        size: number,
        specialStatus: string | undefined,
        dangerInfo: {color: string, progress: number, visual: string, state: 'ACTIVE' | 'BROKEN', fadeRatio: number, centerQ: number, centerR: number, radius: number} | undefined,
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number
    ) {
        // Helper to trace the hex shape at current position
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. SPECIAL STATUS FLOOR EFFECT (Frozen/Polymorph)
        if (specialStatus) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // 2. AOE TELEGRAPH (Danger Zone) - Delegated
        if (dangerInfo) {
            AOERenderer.draw(
                ctx, x, y, size, 
                dangerInfo.color, dangerInfo.visual, dangerInfo.progress, 
                globalTime, q, r,
                dangerInfo.centerQ, dangerInfo.centerR, dangerInfo.radius, // Pass spatial info
                dangerInfo.state, 
                dangerInfo.fadeRatio
            );
        }

        // 3. Dynamic Lighting (Projectile Pass)
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 4. Interactive Highlights (Hover/Range)
        if (isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.1; // Fainter fill
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.6; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.1)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.stroke(); 
            }

            // Only draw unit base ring if not hovering and no danger zone (cleaner look)
            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { TerrainRenderer } from "./TerrainRenderer";

export const AOERenderer = {
    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visual: string,
        progress: number,
        globalTime: number,
        q: number, r: number,
        centerQ: number, centerR: number, maxRadius: number,
        state: 'ACTIVE' | 'BROKEN' = 'ACTIVE',
        fadeRatio: number = 1.0
    ) {
        if (state === 'BROKEN') return;

        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. Calculate Hex Distance from Center
        const dq = q - centerQ;
        const dr = r - centerR;
        const dist = (Math.abs(dq) + Math.abs(dq + dr) + Math.abs(dr)) / 2;

        // 2. Ripple Logic
        // The wave front moves from 0 to maxRadius based on progress (0 -> 1)
        const currentRadius = maxRadius * progress;
        const distDiff = Math.abs(dist - currentRadius);

        ctx.save();

        // --- RIPPLE WAVE (The expanding Ring) ---
        // Light up tiles that are close to the current radius
        // Use a 0.8 threshold to create a slightly thicker band than a single line
        if (distDiff < 0.8) {
            const intensity = 1.0 - (distDiff / 0.8);

            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = color;
            ctx.globalAlpha = intensity * 0.7 * fadeRatio;

            trace();
            ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = intensity * fadeRatio;
            ctx.stroke();
        }

        // --- INNER AREA (Faint Warning) ---
        // Show a faint static indicator for everything inside the blast zone
        // so players know the extent even if the wave passed.
        if (dist <= maxRadius) {
            // Faint fill
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1 * fadeRatio;
            trace();
            ctx.fill();

            // Special Visuals Layer (Cracks, Runes)
            if (visual === 'SMASH' && dist < currentRadius) {
                // Draw cracks only after wave has passed
                ctx.globalAlpha = 0.4 * fadeRatio;
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]);

                // Deterministic random lines based on hex coord
                const seed = Math.abs(q * 13 + r * 7);
                if (seed % 3 === 0) {
                    ctx.beginPath();
                    ctx.moveTo(x - size/2, y); ctx.lineTo(x + size/2, y);
                    ctx.stroke();
                } else if (seed % 3 === 1) {
                    ctx.beginPath();
                    ctx.moveTo(x, y - size/2); ctx.lineTo(x, y + size/2);
                    ctx.stroke();
                }
            } else if (visual === 'ARROW' && dist < currentRadius) {
                // Crosshairs
                if (dist % 2 === 0) {
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 1;
                    ctx.setLineDash([]);
                    ctx.beginPath();
                    ctx.moveTo(x - 5, y); ctx.lineTo(x + 5, y);
                    ctx.moveTo(x, y - 5); ctx.lineTo(x, y + 5);
                    ctx.stroke();
                }
            }
        }

        ctx.restore();
    }
};

import { TerrainRenderer } from "./TerrainRenderer";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the tile face
        size: number,
        color: string,
        type: 'CAST' | 'FIELD',
        visual: string,
        progress: number, // 0-1 for CAST, unused for FIELD usually
        globalTime: number,
        dist: number, // Distance from center of zone (in hexes)
        maxRadius: number
    ) {
        // Trace the hex shape for clipping/filling
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        if (type === 'CAST') {
            this.drawRipple(ctx, x, y, size, color, progress, dist, maxRadius, trace);
        } else if (type === 'FIELD') {
            // Determine field effect based on visual tag
            if (visual === 'BLACK_HOLE' || visual === 'GRAVITY') {
                this.drawGravityZone(ctx, x, y, size, color, globalTime, trace);
            } else {
                // Default to Poison/Fog style for others (DOT, MIST, etc)
                this.drawPoisonZone(ctx, x, y, size, color, globalTime, dist, trace);
            }
        }
    },

    // 1. RIPPLE EFFECT (Instant AOE Pulse)
    drawRipple(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, 
        color: string, 
        progress: number, 
        dist: number, 
        maxRadius: number,
        traceFn: () => void
    ) {
        // Logic: Wave travels from 0 to maxRadius
        const currentRadius = maxRadius * progress;
        const width = 0.8; // Width of the wave band in hexes
        const distDiff = Math.abs(dist - currentRadius);

        ctx.save();

        // Highlight the wave band
        if (distDiff < width) {
            const intensity = 1.0 - (distDiff / width); // 1.0 at center of wave, 0.0 at edges

            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = color;
            ctx.globalAlpha = intensity * 0.6;
            traceFn();
            ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = intensity;
            ctx.stroke();
        }

        // Faint residual fill for entire area (so players know the danger zone)
        if (dist <= maxRadius) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1;
            traceFn();
            ctx.fill();
        }

        ctx.restore();
    },

    // 2. POISON / GAS ZONE (Breathing Grid)
    drawPoisonZone(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, 
        color: string, 
        time: number, 
        dist: number,
        traceFn: () => void
    ) {
        ctx.save();

        // Breathing Alpha: Ripples out from center based on dist
        const breath = 0.3 + 0.15 * Math.sin(time * 2 + dist * 0.5);

        ctx.fillStyle = color;
        ctx.globalAlpha = breath;
        ctx.globalCompositeOperation = 'source-over'; // Fog covers ground
        traceFn();
        ctx.fill();

        // Edge
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        // Rising Bubbles Detail
        // Deterministic bubbles based on tile position (x,y as seed)
        const seed = Math.abs(x + y); 
        const bubbleCount = (seed % 2) + 1; // 1 or 2 bubbles

        ctx.globalCompositeOperation = 'lighter';
        ctx.fillStyle = color;

        for(let i=0; i<bubbleCount; i++) {
            const speed = 20 + (seed % 20);
            const offset = (seed * i * 100);
            const bY = (time * speed + offset) % 40; // Loop 0-40px height
            const bAlpha = 1 - (bY / 40); // Fade out as it rises

            // Wiggle X
            const bX = Math.sin(time * 3 + offset) * 10;

            ctx.globalAlpha = bAlpha * 0.8;
            ctx.beginPath();
            ctx.arc(x + bX, y - bY + 10, 2 + i, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.restore();
    },

    // 3. GRAVITY / BLACK HOLE ZONE (Distorted Grid)
    drawGravityZone(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, 
        color: string, 
        time: number, 
        traceFn: () => void
    ) {
        ctx.save();

        // Base Void Fill
        ctx.fillStyle = '#0f0518'; // Very Dark Void
        ctx.globalAlpha = 0.8;
        traceFn();
        ctx.fill();

        // Pulsing Hex Border (Crushing inward)
        const scale = 0.7 + Math.sin(time * 4) * 0.15;

        ctx.translate(x, y);
        ctx.scale(scale, scale);

        ctx.strokeStyle = color; // Deep Purple usually
        ctx.lineWidth = 2;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.globalCompositeOperation = 'lighter';

        // Draw Hex relative to center (0,0) after translate
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
            const hx = size * Math.cos(angle);
            const hy = size * Math.sin(angle) * ISO_SCALE_Y;
            if (i===0) ctx.moveTo(hx,hy); else ctx.lineTo(hx,hy);
        }
        ctx.closePath();
        ctx.stroke();

        // Inner Singularity Dot
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, 0, 2, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Hex, Skill, Projectile } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

// Lightweight struct to track Zones (Both Instant Casts & Persistent Fields)
interface ZoneSource {
    type: 'CAST' | 'FIELD';
    q: number;
    r: number;
    radius: number; // Hex radius
    radiusSq: number; // For fast distance check (cached)
    color: string;
    visual: string;
    progress: number; // 0-1 for CAST, 1.0 for FIELD
}

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 

export class GridSystem {
    // Cache
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuse buffers
    private _activeZones: ZoneSource[] = [];
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        this.ensureCache(engine);
        const limit = HEX_SIZE * 2; 

        // Find closest tile visual center
        let bestTile: CachedTile | null = null;
        let bestDist = Infinity;

        for (const tile of this._tileCache) {
            const visualY = tile.py - tile.h;
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - visualY);
            if (dist < limit && dist < bestDist) { 
                bestDist = dist;
                bestTile = tile;
            }
        }

        if (bestTile) {
            const testHex = HexUtils.fromPx(wx, wy + bestTile.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === bestTile.q && rounded.r === bestTile.r) {
                return { q: bestTile.q, r: bestTile.r };
            }
        }
        return null;
    }

    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;
            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         if (nHeight > uHeight) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        });
        return occluded;
    }

    submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.ensureCache(engine);

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Reset buffers
        this._activeZones.length = 0;
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        // 1. COLLECT ZONES (Casting & Fields)

        // A. Casting Agents (Telegraphs)
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);

                if (a.stunTimer <= 0 && a.silenceTimer <= 0 && !a.banished && a.castingSkillIdx !== -1) {
                    const s = a.skills[a.castingSkillIdx];
                    if (s && s.type === 'AOE') {
                        let tq = a.q, tr = a.r;
                        if (a.targetHex) { tq = a.targetHex.q; tr = a.targetHex.r; }
                        else if (a.target) { tq = a.target.q; tr = a.target.r; }

                        const progress = 1 - (a.castTimer / s.cast);
                        const radius = (s.aoeRadius || 1);

                        this._activeZones.push({
                            type: 'CAST',
                            q: tq, r: tr,
                            radius: radius,
                            radiusSq: radius + 0.5, // Loose check
                            color: s.color,
                            visual: s.visual || 'BOLT',
                            progress: progress
                        });
                    }
                }
            }
        }

        // B. Persistent Fields (Poison, Gravity, etc.)
        for (const f of engine.fields) {
            // Determine Visual Type based on Skill Properties
            let visual = f.visualType;
            // Map skill CC types to visual themes if generic
            if (f.skill.ccType === 'PULL') visual = 'GRAVITY';
            else if (f.skill.name.includes("黑洞")) visual = 'BLACK_HOLE';

            this._activeZones.push({
                type: 'FIELD',
                q: f.q, r: f.r, // Fields store hex coords now? Check CombatSystem.spawnField logic.
                // Assuming GameEngine fields are updated to track q/r or we deduce it from pos.
                // CombatSystem.spawnField passes `pos` (Point). We should back-calculate hex to be safe.
                // Actually, let's fix spawnField to set q/r correctly or recalculate here.
                // Re-calculating from px for safety:
                // const hex = HexUtils.fromPx(f.pos.x, f.pos.y, engine.mapConfig);
                // Actually `field` has q/r in type definition (BattleField interface in types.ts). 
                // We rely on that being set correctly at spawn.
                radius: f.radius,
                radiusSq: f.radius + 0.5,
                color: f.color,
                visual: visual,
                progress: 1.0 // Fields are always "full" active
            });
        }

        // 2. ITERATE TILES
        const PROJ_LIGHT_RADIUS_SQ = 1600; // 40^2

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualY = py + offset;

            if (visualY > py + 800) continue;

            const k = `${q},${r}`;

            // --- SUBMIT OBSTACLE ---
            const obstacleType = engine.obstacles.get(k);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = visualY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualY - h - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // --- SUBMIT TERRAIN ---
            // Determine Overlapping Zone
            // Priority: Render Fields over Casts? Or blend? 
            // We just pick the first match for simplicity/perf. 
            // Maybe prioritize FIELD (Damage) over CAST (Warning).

            let zoneInfo = undefined;

            // Sort zones: Fields first? No, simple iteration.
            for (const zone of this._activeZones) {
                const dist = (Math.abs(q - zone.q) + Math.abs(q + r - zone.q - zone.r) + Math.abs(r - zone.r)) / 2;

                if (dist <= zone.radius) {
                    zoneInfo = {
                        type: zone.type,
                        color: zone.color,
                        visual: zone.visual,
                        progress: zone.progress,
                        centerQ: zone.q, 
                        centerR: zone.r, 
                        radius: zone.radius,
                        dist: dist // Pass exact distance for shaders
                    };
                    // Break on first found? Or blend? 
                    // Let's break to avoid overdraw. First valid zone wins.
                    break; 
                }
            }

            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const bonus = Math.max(0, Math.floor((agentH - h) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;
                const dist = (Math.abs(q - highlightAgent.q) + Math.abs(q + r - highlightAgent.q - highlightAgent.r) + Math.abs(r - highlightAgent.r)) / 2;

                if (dist <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = visualY; 
            op.z = 0;

            op.tx = px; 
            op.ty = visualY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q;
            op.tr = r;

            // Overlays
            op.oStatus = specialStatus;
            op.oDanger = zoneInfo; // Reusing oDanger slot for generalized ZoneInfo
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange;
            op.oRangeCol = rangeColor;
            op.oHover = isHover;
            op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { TerrainRenderer } from "./TerrainRenderer";
import { ZoneRenderer } from "./ZoneRenderer";

// Updated Interface matching GridSystem
interface ZoneInfo {
    type: 'CAST' | 'FIELD';
    color: string;
    visual: string;
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual top Y
        size: number,
        specialStatus: string | undefined,
        zoneInfo: ZoneInfo | undefined, // Replaces dangerInfo
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number
    ) {
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. SPECIAL STATUS FLOOR EFFECT
        if (specialStatus) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // 2. ZONE RENDERING (Cast Ripple / Persistent Fields)
        if (zoneInfo) {
            ZoneRenderer.draw(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.type,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // 3. Dynamic Lighting
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 4. Interactive Highlights
        if (isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.1;
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.6; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.1)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.stroke(); 
            }

            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, BattleField } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { SkillResolutionSystem } from "./combat/SkillResolutionSystem";
import { HexUtils, Vector } from "../utils";
import { HEX_SIZE } from "../../constants";
import * as VFXSpawners from "./vfx/spawners";

const FIELD_TICK_RATE = 0.5; // Damage every 0.5s

export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public skillResolution: SkillResolutionSystem;

    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.skillResolution = new SkillResolutionSystem();
    }

    // Proxy for accessors to maintain GameEngine compatibility
    get projectiles(): Projectile[] { return this.projectileSystem.projectiles; }
    set projectiles(v: Projectile[]) { this.projectileSystem.projectiles = v; }

    public update(dt: number, engine: GameEngine) {
        // 1. Casting Updates (Logic)
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.skillResolution.updateCasting(a, dt, engine);
            }
        });

        // 2. Projectile Physics & Impacts
        this.projectileSystem.update(dt, engine, this.skillResolution);

        // 3. Update Persistent Ground Fields (Poison clouds, etc.)
        this.updateFields(dt, engine);

        // 4. Update Field Physics (Gravity/Suction - Per Frame)
        this.updateFieldPhysics(dt, engine);
    }

    private updateFields(dt: number, engine: GameEngine) {
        // Reverse iterate to remove expired fields safely
        for (let i = engine.fields.length - 1; i >= 0; i--) {
            const field = engine.fields[i];

            field.duration -= dt;
            field.tickTimer -= dt;

            // Handle Logic Tick
            if (field.tickTimer <= 0) {
                field.tickTimer = FIELD_TICK_RATE;
                this.resolveFieldTick(field, engine);
            }

            // Expiry
            if (field.duration <= 0) {
                engine.fields.splice(i, 1);
            }
        }
    }

    private updateFieldPhysics(dt: number, engine: GameEngine) {
        // Optimized physics loop for continuous effects (Black Hole / Gravity)
        // This runs every frame, unlike damage ticks.

        for (const field of engine.fields) {
            // Only 'PULL' fields generate gravity
            if (field.skill.ccType !== 'PULL' && field.skill.ccType2 !== 'PULL') continue;

            const rPxSq = field.radiusPx * field.radiusPx;
            const pullForce = (field.skill.ccForce || 5) * 150; // Base force multiplier

            engine.agents.forEach(agent => {
                if (agent.hp <= 0 || agent.banished || agent.team === field.team) return;

                const dx = field.pos.x - agent.px;
                const dy = field.pos.y - agent.py;
                const distSq = dx * dx + dy * dy;

                if (distSq <= rPxSq && distSq > 100) { // Don't pull if already at center (jitter fix)
                    // 1. GRAVITY: Apply force towards center
                    // We calculate a normalized vector
                    const dist = Math.sqrt(distSq);
                    const nx = dx / dist;
                    const ny = dy / dist;

                    // Apply continuous acceleration
                    // We rely on PhysicsEngine damping to prevent infinite speed
                    agent.physics.vx += nx * pullForce * dt;
                    agent.physics.vy += ny * pullForce * dt;

                    // 2. EVENT HORIZON: Massive Slow
                    // If you are in a black hole, you can barely walk away
                    agent.moveSpeedMult = 0.3; // 70% Slow override
                }
            });
        }
    }

    private resolveFieldTick(field: BattleField, engine: GameEngine) {
        const source = engine.agents.find(a => a.id === field.sourceId);

        const rPx = field.radiusPx * field.radiusPx;

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished || agent.team === field.team) return; // Friendly fire OFF

            const dx = agent.px - field.pos.x;
            const dy = agent.py - field.pos.y;
            const distSq = dx * dx + dy * dy;

            if (distSq <= rPx) {
                // Determine damage. 
                // Use ccForce if available, otherwise 20% of power.
                // For Black Holes, damage is usually low per tick but high utility.
                const damage = (field.skill.power * 0.2) || 10;

                // Direct HP modification
                agent.hp = Math.max(0, agent.hp - damage);

                // Add tiny floating text
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(damage), 
                    color: field.color 
                });

                // Apply Status Effect if applicable (Refresh DoT timer)
                // Note: We don't apply PULL here, that's handled in updateFieldPhysics
                if (field.skill.ccType && field.skill.ccType !== 'PULL') {
                    this.skillResolution.applyCC(
                        source || agent, agent, field.skill, 
                        field.skill.ccType, 1.0, 0, undefined, engine
                    );
                }
            }
        });
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }

    public spawnField(source: Agent, skill: Skill, pos: {x: number, y: number}, engine: GameEngine) {
        // Convert radius to pixels
        const radiusGrid = skill.aoeRadius || 1;
        const radiusPx = radiusGrid * HEX_SIZE * 1.5; // Approximation for coverage

        // Determine Duration: Use ccDur if > 0, else default 5s
        const duration = (skill.ccDur && skill.ccDur > 0) ? skill.ccDur : 5.0;

        // Calculate Q, R from Pos for Grid Lookup
        const hex = HexUtils.fromPx(pos.x, pos.y, engine.mapConfig);

        const field: BattleField = {
            id: Math.random().toString(36).substr(2, 5),
            pos: pos,
            q: hex.q, 
            r: hex.r, 
            radius: radiusGrid,
            radiusPx: radiusPx,
            skill: skill,
            sourceId: source.id,
            team: source.team,
            duration: duration,
            tickTimer: 0, // Tick immediately on spawn
            visualType: skill.visual || 'SMOKE',
            color: skill.color
        };

        engine.fields.push(field);

        // Spawn Visuals immediately (Just initial puff, persistent zone handled by ZoneRenderer)
        VFXSpawners.spawnLingeringField(engine.renderer!.vfx, pos.x, pos.y, skill.color, 'SMOKE', 1.0, 0);
    }
}

