    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING' | 'BLAST' | 'SHOCKWAVE', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30; // Default size
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                // Only spawn impact if it wasn't a projectile hit (which handles its own visuals)
                // or if it's a direct instant damage event.
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                // 1. UNIVERSAL GRID REACTION (The "Floor Tile Explosion")
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    // 2. SPECIALIZED ULTIMATE VFX (Cinematic Layer)
                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // --- IMPERIAL (BLUE) ULTIMATES ---
                    // 🛡️ TANK: Divine Territory (Sanctuary)
                    if (id === 'tb_u1') {
                        VFXSpawners.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7);
                        return;
                    }
                    // ⚔️ WARRIOR: Daybreak (Sun Strike)
                    if (id === 'wb_u2') {
                        VFXSpawners.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🏹 RANGER: Crystal Arrow / Starfall
                    if (id === 'rb_u1' || id === 'rb_u2') {
                        VFXSpawners.spawnImperialJudgment(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🔮 MAGE: Absolute Zero (Frostfall)
                    if (id === 'mb_u2') {
                        VFXSpawners.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5);
                        return;
                    }
                    // ⚕️ SUPPORT: Divine Intervention (Miracle)
                    if (id === 'sb_u1' || id === 'sb_u2') {
                        VFXSpawners.spawnImperialMiracle(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4);
                        return;
                    }

                    // --- RED FACTION / CHAOS ULTS ---
                    // ☢️ Tactical Nuke (Ranger Red Ult 2)
                    if (id === 'rr_u2') {
                        VFXSpawners.spawnTacticalNuke(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); 
                        return;
                    }
                    // ☄️ Meteor (Mage Red Ult 1)
                    if (id === 'mr_u1') {
                        VFXSpawners.spawnMeteorImpact(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🕳️ Black Hole (Mage Blue Ult 1 - Event Horizon)
                    if (id === 'mb_u1') {
                        VFXSpawners.spawnBlackHoleCollapse(vfx, event.pos.x, visualGroundY, '#000');
                        camera.addTrauma(0.4);
                        return;
                    }

                    // Generic Grid Reaction for non-special AOEs
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // 3. GENERIC AOE BLAST (Fallback)
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    // For AOE hits, we skip individual pillars/rituals to prevent visual clutter
                    // But we still show impact debris/flash
                    const hitColor = event.skill?.color || '#fff';
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05);
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                // Special Visual for Death Finger (mr_u2)
                if (event.skill?.id === 'mr_u2') {
                    VFXSpawners.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); // Minimized
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // Special handling for Death Finger (mr_u2) target hit - KILL THE PILLAR
            if (skill && skill.id === 'mr_u2') {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; // Early return prevents BloodRitual
            }

            // 1. FACTION RITUAL (The Ground Effect)
            if (faction === Team.BLUE) {
                // For Blue faction normal ult hits (single target), use a smaller fast pillar
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 0.6, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } else {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }

        } else {
            if (visualType === 'SMASH') {
                VFXSpawners.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 256; // Increased resolution for crisp runes
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper: Chaos color detection (Red/Purple/Dark) vs Order (Blue/Gold/White)
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') ||
           c.includes('#1c');
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         // Clear previous styles
         ctx.globalCompositeOperation = 'source-over';

         if (isChaos) {
             // CHAOS: Unstable Plasma Core
             // Darker center, jagged edges
             const grad = ctx.createRadialGradient(cx, cy, r*0.1, cx, cy, r);
             grad.addColorStop(0, '#ffffff');
             grad.addColorStop(0.3, color);
             grad.addColorStop(0.6, 'rgba(0,0,0,0.8)'); // Dark halo
             grad.addColorStop(1, 'transparent');

             ctx.fillStyle = grad;

             // Jagged star shape
             ctx.beginPath();
             const spikes = 12;
             for(let i=0; i<spikes*2; i++) {
                 const angle = (i / (spikes*2)) * Math.PI * 2;
                 const rad = (i % 2 === 0) ? r : r * 0.4;
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();

         } else {
             // ORDER: Perfect Lens Flare / Star
             // Soft gaussian feel with distinct cross spike
             const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
             grad.addColorStop(0, '#ffffff');        
             grad.addColorStop(0.15, color);          
             grad.addColorStop(0.5, color);          
             grad.addColorStop(1, 'rgba(0,0,0,0)');  

             ctx.fillStyle = grad;
             ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();

             // Cross flare
             ctx.fillStyle = '#fff';
             ctx.globalAlpha = 0.8;
             ctx.beginPath();
             ctx.ellipse(cx, cy, r * 0.8, r * 0.1, 0, 0, Math.PI*2);
             ctx.ellipse(cx, cy, r * 0.1, r * 0.8, 0, 0, Math.PI*2);
             ctx.fill();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.15; // Very subtle

        // Organic irregular blobs
        for(let i=0; i<12; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.3);
            const r = FOG_SIZE * (0.15 + Math.random() * 0.2);

            ctx.beginPath(); 
            ctx.ellipse(
                cx + Math.cos(angle)*dist, 
                cy + Math.sin(angle)*dist, 
                r, r * 0.6, 
                Math.random() * Math.PI, 
                0, Math.PI*2
            ); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = MAGIC_CIRCLE_SIZE * 0.45;
        const isChaos = isChaosStyle(color);

        ctx.strokeStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.lineWidth = 3;
        ctx.lineJoin = 'round';

        if (isChaos) {
            // CHAOS: Jagged, Ancient Runes, Broken Circles
            // Outer Ring (Broken)
            ctx.beginPath();
            for(let i=0; i<8; i++) {
                const start = (i / 8) * Math.PI * 2;
                ctx.arc(cx, cy, radius, start + 0.1, start + (Math.PI*2/8) - 0.1);
            }
            ctx.stroke();

            // Inner Pentagram-ish mess
            ctx.lineWidth = 2;
            ctx.beginPath();
            const points = 7; 
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 4 / points); // Skip points
                const r = radius * 0.8;
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.stroke();

            // Blood/Dark fill center
            const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');
            ctx.globalAlpha = 0.2;
            ctx.fillStyle = grad;
            ctx.fill();

        } else {
            // ORDER: Geometric, Tech/Holy, Concentric
            // Outer double ring
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1;
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius * 0.95, 0, Math.PI * 2); 
            ctx.stroke();

            // Geometric Pattern (Square + Rotated Square)
            ctx.lineWidth = 2;
            const drawPoly = (sides: number, r: number, offset: number) => {
                ctx.beginPath();
                for (let i = 0; i <= sides; i++) {
                    const angle = offset + (i * Math.PI * 2) / sides;
                    const x = cx + Math.cos(angle) * r;
                    const y = cy + Math.sin(angle) * r;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.stroke();
            };

            drawPoly(4, radius * 0.7, 0);
            drawPoly(4, radius * 0.7, Math.PI/4);

            // Inner Tech Circle
            ctx.beginPath(); ctx.arc(cx, cy, radius * 0.3, 0, Math.PI*2); ctx.stroke();

            // Runes (Dots)
            ctx.fillStyle = '#fff';
            for(let i=0; i<12; i++) {
                const a = (i/12) * Math.PI*2;
                const px = cx + Math.cos(a) * radius * 0.85;
                const py = cy + Math.sin(a) * radius * 0.85;
                ctx.beginPath(); ctx.arc(px, py, 2, 0, Math.PI*2); ctx.fill();
            }
        }

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // Energy Arrow
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();

                // Head
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8);
                ctx.fill();
                // Fletching
                ctx.strokeStyle = color;
                ctx.beginPath();
                ctx.moveTo(20, cy); ctx.lineTo(10, cy - 6);
                ctx.moveTo(20, cy); ctx.lineTo(10, cy + 6);
                ctx.stroke();
                break;

            case 'FIREBALL':
            case 'BOMB':
                // Magma Core
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 20);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.2, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;
                ctx.beginPath(); ctx.arc(cx + 20, cy, 18, 0, Math.PI * 2); ctx.fill();
                break;

            case 'SLASH':
                // Crescent Wave
                ctx.translate(cx, cy);
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.arc(0, 0, 30, -Math.PI/2, Math.PI/2, false);
                ctx.bezierCurveTo(10, 20, 10, -20, 0, -30);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                // Magic Missile (Tapered slug)
                const grad = ctx.createLinearGradient(0, 0, PROJ_WIDTH, 0);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.5, color);
                grad.addColorStop(1, '#fff');

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2);
                ctx.fill();

                // Core
                ctx.fillStyle = '#fff';
                ctx.beginPath();
                ctx.ellipse(cx + 15, cy, 10, 3, 0, 0, Math.PI*2);
                ctx.fill();
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.scale(1, 0.5); // Perspective squash

        if (isChaos) {
            // Chaos: Cracks and Scorch
            ctx.fillStyle = '#1a0505'; // Dark scorch
            ctx.globalAlpha = 0.8;
            ctx.beginPath();
            ctx.arc(cx, cy*2, 40, 0, Math.PI*2);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.6;
            ctx.beginPath();
            ctx.moveTo(cx, cy*2); ctx.lineTo(cx+30, cy*2-20);
            ctx.moveTo(cx, cy*2); ctx.lineTo(cx-20, cy*2+30);
            ctx.moveTo(cx, cy*2); ctx.lineTo(cx+10, cy*2+40);
            ctx.stroke();

        } else {
            // Order: Clean Energy Residual
            const grad = ctx.createRadialGradient(cx, cy * 2, 10, cx, cy * 2, 50);
            grad.addColorStop(0, color); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.arc(cx, cy * 2, 50, 0, Math.PI*2); ctx.fill();

            // Ring
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.3;
            ctx.beginPath(); ctx.arc(cx, cy * 2, 40, 0, Math.PI*2); ctx.stroke();
        }

        return canvas;
    }
};

