        p.color = isPhysical ? '#e2e8f0' : color; 
        p.size = 4 + Math.random() * 6; // Larger kinetic sparks
        p.type = 'SPARK'; 
        p.delay = 0;
        system.state.particles.push(p);
    }

    if (isPhysical) {
        spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');
    } else {
        // Magical impact ring
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = color;
        p.size = 20; 
        p.type = 'RING';
        system.state.particles.push(p);
    }
}

export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = 0.25; p.maxLife = 0.25;
    p.color = color; p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

// 💥 IMPROVED UNIT SHATTER 💥
export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const isBlue = team === Team.BLUE;

    const theme = isBlue ? THEME_IMPERIAL : THEME_COVENANT;
    const baseColor = isBlue ? '#94a3b8' : '#27272a'; // Base debris (Pedestal)
    const armorColor = theme.primary; // Armor chunks
    const glowColor = isBlue ? THEME_IMPERIAL.energy : theme.secondary; // Soul energy

    // 1. Icon Sprite (Spinning out)
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 60; 
    const angle = Math.random() * Math.PI * 2;
    p.vx = Math.cos(angle) * 150; 
    p.vy = Math.sin(angle) * 150; 
    p.vz = 350; // Pop up high
    p.life = 1.5; p.maxLife = 1.5;
    p.color = '#fff'; p.size = 64 * 0.6; 
    p.type = 'SPRITE'; p.image = assets.icon;
    p.rotation = Math.random() * Math.PI * 2; 
    p.vRotation = (Math.random() - 0.5) * 40; // Fast spin
    system.state.particles.push(p);

    // 2. Base Debris (Heavy, Darker)
    for (let i = 0; i < 5; i++) {
        const p = system.state.getParticle();
        const angle = (i / 5) * Math.PI * 2;
        p.x = x; p.y = y; p.z = 10;
        // Explode outward
        const speed = 150 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; 
        p.vy = Math.sin(angle) * speed; 
        p.vz = 150 + Math.random() * 150; 
        p.life = 2.0; p.maxLife = 2.0;
        p.color = baseColor; 
        p.size = 8 + Math.random() * 8; // Chunky
        p.type = 'DEBRIS'; 
        p.rotation = angle; 
        p.vRotation = (Math.random()-0.5)*15;
        system.state.particles.push(p);
    }

    // 3. Armor Shards (Light, Neon/Colored)
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        p.x = x; p.y = y; p.z = 40; // Higher center
        // Fly further
        const speed = 200 + Math.random() * 200;
        p.vx = Math.cos(angle) * speed; 
        p.vy = Math.sin(angle) * speed; 
        p.vz = 250 + Math.random() * 250; 
        p.life = 1.5; p.maxLife = 1.5;
        p.color = Math.random() > 0.5 ? armorColor : theme.secondary; 
        p.size = 5 + Math.random() * 5; // Smaller, sharper
        p.type = 'SHARD'; 
        p.rotation = angle; 
        p.vRotation = (Math.random()-0.5)*25;
        system.state.particles.push(p);
    }

    // 4. Soul Release (Vertical Beam/Glow)
    const soul = system.state.getParticle();
    soul.x = x; soul.y = y; soul.z = 10;
    soul.vx = 0; soul.vy = 0; soul.vz = 20; // Slowly rise
    soul.life = 0.8; soul.maxLife = 0.8;
    soul.color = glowColor;
    soul.size = 120;
    soul.type = 'PILLAR'; // Use miniature pillar effect
    system.state.particles.push(soul);

    // 5. Ground Scorch
    addDecal(system, x, y, '#000'); 
    spawnShockwave(system, x, y, glowColor, 0.4);
    spawnExplosion(system, x, y, 40, 15, baseColor, 0.8, 0.8, 'SMOKE');
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        // Higher velocity spread for kinetic feel
        const spd = Math.random() * 200 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 200 + 100) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        // Size varies more
        p.size = type === 'SPARK' ? Math.random() * 4 + 3 : Math.random() * 20 + 20;
        if (type === 'SHARD' || type === 'DEBRIS') p.size = 5 + Math.random() * 5;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnDivinePillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING' | 'BLAST' | 'SHOCKWAVE', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30; // Default size
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                // Only spawn impact if it wasn't a projectile hit (which handles its own visuals)
                // or if it's a direct instant damage event.
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                // 1. UNIVERSAL GRID REACTION (The "Floor Tile Explosion")
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    // 2. SPECIALIZED ULTIMATE VFX (Cinematic Layer)
                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // --- IMPERIAL (BLUE) ULTIMATES ---
                    // 🛡️ TANK: Divine Territory (Sanctuary)
                    if (id === 'tb_u1') {
                        VFXSpawners.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7);
                        return;
                    }
                    // ⚔️ WARRIOR: Daybreak (Sun Strike)
                    if (id === 'wb_u2') {
                        VFXSpawners.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🏹 RANGER: Crystal Arrow / Starfall
                    if (id === 'rb_u1' || id === 'rb_u2') {
                        VFXSpawners.spawnImperialJudgment(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🔮 MAGE: Absolute Zero (Frostfall)
                    if (id === 'mb_u2') {
                        VFXSpawners.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5);
                        return;
                    }
                    // ⚕️ SUPPORT: Divine Intervention (Miracle)
                    if (id === 'sb_u1' || id === 'sb_u2') {
                        VFXSpawners.spawnImperialMiracle(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4);
                        return;
                    }

                    // --- RED FACTION / CHAOS ULTS ---
                    // ☢️ Tactical Nuke (Ranger Red Ult 2)
                    if (id === 'rr_u2') {
                        VFXSpawners.spawnTacticalNuke(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); 
                        return;
                    }
                    // ☄️ Meteor (Mage Red Ult 1)
                    if (id === 'mr_u1') {
                        VFXSpawners.spawnMeteorImpact(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🕳️ Black Hole (Mage Blue Ult 1 - Event Horizon)
                    if (id === 'mb_u1') {
                        VFXSpawners.spawnBlackHoleCollapse(vfx, event.pos.x, visualGroundY, '#000');
                        camera.addTrauma(0.4);
                        return;
                    }

                    // Generic Grid Reaction for non-special AOEs
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // 3. GENERIC AOE BLAST (Fallback)
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    // For AOE hits, we skip individual pillars/rituals to prevent visual clutter
                    // But we still show impact debris/flash
                    const hitColor = event.skill?.color || '#fff';
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05);
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                // Special Visual for Death Finger (mr_u2)
                if (event.skill?.id === 'mr_u2') {
                    VFXSpawners.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); // Minimized
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // Special handling for Death Finger (mr_u2) target hit - KILL THE PILLAR
            if (skill && skill.id === 'mr_u2') {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; // Early return prevents BloodRitual
            }

            // 1. FACTION RITUAL (The Ground Effect)
            if (faction === Team.BLUE) {
                // For Blue faction normal ult hits (single target), use a smaller fast pillar
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 0.6, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } else {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }

        } else {
            if (visualType === 'SMASH') {
                VFXSpawners.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";
import { HEX_SIZE } from "../../../constants";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

// COLORS
const COL_PURPLE = '#8b5cf6'; // Violet-500
const COL_GOLD = '#facc15';   // Yellow-400
const COL_CRIMSON = '#ef4444'; // Red-500

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    // We are at Ground Level (0,0) in the scaled context.
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    // Rotating Rune Ring - Clear indication of ground position
    ctx.save();
    ctx.scale(1, 0.58); // Isometric flat on ground
    // Use lineDashOffset to simulate rotation without distorting the ellipse
    ctx.lineDashOffset = -t * 20;

    // Outer dashed ring
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    // Only visible if unit is airborne to show connection
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); // Fade out near unit feet

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        // Draw Main Tether Line
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        // Draw Moving Energy Pulses up the tether
        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; // 0 to 1, faster speed
            const px = feetX * p;
            const py = feetY * p;

            // Draw small horizontal dash/disk traveling up
            // Scale based on height to simulate perspective
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); // Faster spin for thrusters

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    // 3 Arcs for stability look
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; // Flicker
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    if (skill.tag === 'ULT') {
        drawUltimateChantVFX(ctx, agent, t);
        return;
    }

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

// 🌀 ULTIMATE BODY GLOW (Intense Core Accumulation)
export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    // Intense Core Glow (Chest)
    // Pulsing increases speed as cast finishes
    const pulseSpeed = 10 + progress * 20; 
    const pulse = 1 + Math.sin(t * pulseSpeed) * (0.1 + progress * 0.2);

    // Outer Aura
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3 * progress;
    ctx.beginPath();
    ctx.arc(0, -40, 45 * pulse, 0, Math.PI*2);
    ctx.fill();

    // Inner Core
    ctx.globalAlpha = 0.6 * progress;
    ctx.beginPath();
    ctx.arc(0, -40, 25 * pulse, 0, Math.PI*2);
    ctx.fill();

    // White Hot Center (Critical Mass)
    ctx.fillStyle = '#fff';
    ctx.globalAlpha = 0.8 * progress * progress; // Quadratic ramp up
    ctx.beginPath();
    ctx.arc(0, -40, 10 * pulse, 0, Math.PI*2);
    ctx.fill();

    // Rising Particles (Spirit Bomb style)
    if (progress > 0.2) {
        const pCount = 5;
        for(let i=0; i<pCount; i++) {
            const angle = (t * 5 + i) % (Math.PI*2);
            const dist = 60 * (1 - ((t + i*0.2) % 1)); // Suck INWARD
            const px = Math.cos(angle) * dist;
            const py = -40 + Math.sin(angle) * dist;

            ctx.fillStyle = color;
            ctx.globalAlpha = 0.5 * progress;
            ctx.beginPath(); ctx.arc(px, py, 2, 0, Math.PI*2); ctx.fill();
        }
    }

    ctx.restore();
}

// 🌀 ULTIMATE DOMAIN EXPANSION (The Main Event)
// Draws the expanding magical circle on the ground during casting
export function drawUltimateGroundCircle(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, t: number, progress: number, skillRadius: number = 1, isAOE: boolean) {
    ctx.save();
    ctx.translate(x, y);
    ctx.globalCompositeOperation = 'lighter';

    // --- EXPANSION LOGIC ---
    // If AOE: Expands from 0 to Full Radius
    // If Single: Pulses at fixed size (small)

    // Calculate Target Radius in Pixels (Hex Size * Grid Radius * Buffer)
    const targetPx = isAOE ? (skillRadius * HEX_SIZE) : (HEX_SIZE * 1.2);

    // Animation Curve: Ease Out Quart (Fast start, slow finish)
    const ease = 1 - Math.pow(1 - progress, 4);

    // Current Radius
    const currentR = isAOE ? (targetPx * ease) : targetPx;

    // ISO Flatten
    ctx.save();
    ctx.scale(1, 0.58);

    // 1. The Boundary Ring (Thick)
    ctx.beginPath();
    ctx.arc(0, 0, currentR, 0, Math.PI * 2);
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;

    // Rotation for dynamic feel
    const rot = t * 2;
    ctx.setLineDash([20, 15]); // Runes/Segments
    ctx.lineDashOffset = -rot * 20;

    ctx.globalAlpha = 0.8 * progress; // Fade in opacity
    ctx.stroke();

    // 2. The Fill (Domain Presence)
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.15 * progress;
    ctx.fill();

    // 3. Inner Concentric Rings (Sonar effect)
    if (progress > 0.1) {
        const innerR = currentR * 0.6;
        ctx.beginPath();
        ctx.arc(0, 0, innerR, 0, Math.PI * 2);
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.lineDashOffset = rot * 30; // Counter rotate
        ctx.strokeStyle = '#fff';
        ctx.globalAlpha = 0.4 * progress;
        ctx.stroke();
    }

    ctx.restore(); // End Iso

    // 4. Vertical Beacon (Connecting Caster to Domain Center)
    if (progress > 0.05) {
        const beamW = Math.min(40, currentR * 0.5);
        const beamH = 800; // Sky height

        const grad = ctx.createLinearGradient(0, 0, 0, -beamH);
        grad.addColorStop(0, color);
        grad.addColorStop(0.1, 'rgba(255,255,255,0.5)'); // Bright base
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.2 * progress + (Math.sin(t*15)*0.05);
        ctx.fillRect(-beamW/2, -beamH, beamW, beamH);
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
