import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // =================================================================
                    // 🔵 IMPERIAL (BLUE) ULTIMATE VFX MAPPING
                    // =================================================================

                    // 🛡️ TANK: Divine Territory (Sanctuary)
                    if (id === 'tb_u1') {
                        VFXSpawners.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7);
                        return;
                    }
                    // 🛡️ TANK: Kings Blessing (Invuln)
                    if (id === 'tb_u2') {
                        VFXSpawners.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }
                    // ⚔️ WARRIOR: Thunder Jump (Shockwave)
                    if (id === 'wb_u1') {
                        VFXSpawners.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // ⚔️ WARRIOR: Daybreak (Sun Strike)
                    if (id === 'wb_u2') {
                        VFXSpawners.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🏹 RANGER: Crystal Arrow (Shatter)
                    if (id === 'rb_u1') {
                        VFXSpawners.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🏹 RANGER: Starfall (Rain)
                    if (id === 'rb_u2') {
                        VFXSpawners.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4);
                        return;
                    }
                    // 🔮 MAGE: Black Hole (Gravity)
                    if (id === 'mb_u1') {
                        VFXSpawners.spawnBlackHoleCollapse(vfx, event.pos.x, visualGroundY, '#0f172a');
                        camera.addTrauma(0.5);
                        return;
                    }
                    // 🔮 MAGE: Absolute Zero (Frostfall)
                    if (id === 'mb_u2') {
                        VFXSpawners.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5);
                        return;
                    }
                    // ⚕️ SUPPORT: Divine Intervention (Miracle)
                    if (id === 'sb_u1') {
                        VFXSpawners.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }
                    // ⚕️ SUPPORT: Resurrection (Full Heal)
                    if (id === 'sb_u2') {
                        VFXSpawners.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4);
                        return;
                    }

                    // =================================================================
                    // 🔴 COVENANT (RED) ULTIMATE VFX MAPPING
                    // =================================================================

                    // 🛡️ TANK: Guillotine (Vertical Slash)
                    if (id === 'tr_u1') {
                        VFXSpawners.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🛡️ TANK: Undead Army (Necrotic Ground)
                    if (id === 'tr_u2') {
                        VFXSpawners.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5);
                        return;
                    }
                    // ⚔️ WARRIOR: Ragnarok (Magma Eruption)
                    if (id === 'wr_u1') {
                        VFXSpawners.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.9);
                        return;
                    }
                    // ⚔️ WARRIOR: Blood Storm (Tornado)
                    if (id === 'wr_u2') {
                        VFXSpawners.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🏹 RANGER: Final Blast (Railgun)
                    if (id === 'rr_u1') {
                        // Railgun visual handled mostly by projectile trail, but here's the impact
                        VFXSpawners.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🏹 RANGER: Nuke (Mushroom Cloud)
                    if (id === 'rr_u2') {
                        VFXSpawners.spawnTacticalNuke(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); 
                        return;
                    }
                    // 🔮 MAGE: Meteor (Falling Rock)
                    if (id === 'mr_u1') {
                        VFXSpawners.spawnMeteorImpact(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🔮 MAGE: Finger of Death (Already handled in Beam, but here for AOE fallback)
                    if (id === 'mr_u2') {
                        VFXSpawners.spawnDeathRay(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.7);
                        return;
                    }
                    // ⚕️ SUPPORT: Soul Link (Void Web)
                    if (id === 'sr_u1') {
                        VFXSpawners.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }
                    // ⚕️ SUPPORT: Ancestral Spirit (Rising Spirits)
                    if (id === 'sr_u2') {
                        VFXSpawners.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }

                    // Generic Grid Reaction
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05);
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                // Red Mage Death Finger (mr_u2) - Single Target Special
                if (event.skill?.id === 'mr_u2') {
                    VFXSpawners.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // Death Finger target hit check
            if (skill && skill.id === 'mr_u2') {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            // FACTION RITUAL (Ult Hit)
            if (faction === Team.BLUE) {
                // Remove Pillar fallback. Use pure explosion/shockwave.
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                // Red faction uses Blood Ritual
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hits
            if (visualType === 'SMASH') {
                VFXSpawners.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { TerrainRenderer } from "./TerrainRenderer";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the tile face
        size: number,
        color: string,
        type: 'CAST' | 'FIELD',
        visual: string,
        progress: number, // 0-1 for CAST, unused for FIELD usually
        globalTime: number,
        dist: number, // Distance from center of zone (in hexes)
        maxRadius: number
    ) {
        // Trace the hex shape for clipping/filling
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        if (type === 'CAST') {
            this.drawRipple(ctx, x, y, size, color, visual, progress, dist, maxRadius, trace);
        } else if (type === 'FIELD') {
            // Determine field effect based on visual tag
            this.drawPersistentField(ctx, x, y, size, color, visual, globalTime, dist, trace);
        }
    },

    // 1. RIPPLE EFFECT (The Wave)
    // Principle: Grid-based propagation. Only light up tiles currently touched by the wave.
    drawRipple(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, 
        color: string, 
        visual: string,
        progress: number, 
        dist: number, 
        maxRadius: number,
        traceFn: () => void
    ) {
        // Calculate the current radius of the expanding wave
        // We expand slightly past maxRadius to ensure the last tile finishes animating
        const currentRadius = maxRadius * (progress * 1.2); 

        // The "Band" of the wave. Tiles within this distance range are "active".
        const waveWidth = 1.5; 
        const distDiff = currentRadius - dist;

        ctx.save();

        // A. WAVE FRONT (The leading edge)
        if (distDiff >= 0 && distDiff < waveWidth) {
            // Intensity based on position in the wave (Head is bright, Tail is dim)
            const intensity = distDiff / waveWidth; // 0 to 1
            const alpha = Math.sin(intensity * Math.PI); // Smooth curve

            ctx.globalCompositeOperation = 'lighter';

            // Fill
            ctx.fillStyle = color;
            ctx.globalAlpha = alpha * 0.6;
            traceFn();
            ctx.fill();

            // Border Highlight
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha;
            ctx.stroke();
        }

        // B. RESIDUAL GROUND (The scorched earth left behind)
        // If the wave has passed this tile (dist < currentRadius), show a lingering effect
        // Fade out as cast finishes (progress -> 1)
        if (dist < currentRadius && dist <= maxRadius) {
            const fade = 1.0 - progress;

            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.15 * fade;
            traceFn();
            ctx.fill();

            // Specific Visual Decor
            ctx.globalAlpha = 0.4 * fade;
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;

            if (visual === 'SMASH' || visual === 'BOMB') {
                // Cracks
                ctx.beginPath();
                ctx.moveTo(x - 10, y); ctx.lineTo(x + 5, y + 5); ctx.lineTo(x + 10, y - 5);
                ctx.stroke();
            } else if (visual === 'ARROW') {
                // Target marks
                ctx.setLineDash([2, 4]);
                ctx.beginPath();
                ctx.arc(x, y, size * 0.6, 0, Math.PI * 2);
                ctx.stroke();
                ctx.setLineDash([]);
            } else if (visual === 'BOLT' || visual === 'BEAM') {
                // Runes
                ctx.beginPath();
                ctx.arc(x, y, 4, 0, Math.PI*2);
                ctx.stroke();
            }
        }

        ctx.restore();
    },

    // 2. PERSISTENT FIELD (Continuous Zone)
    // Principle: Every tile in the zone must have active visuals.
    drawPersistentField(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, 
        color: string, 
        visual: string,
        time: number, 
        dist: number,
        traceFn: () => void
    ) {
        ctx.save();

        if (visual === 'BLACK_HOLE' || visual === 'PULL') {
            // --- GRAVITY / VOID ---
            // Distorted Grid inward
            const scale = 0.8 + Math.sin(time * 3 + dist) * 0.1;

            // Dark Void Base
            ctx.fillStyle = '#020617'; 
            ctx.globalAlpha = 0.7;
            traceFn();
            ctx.fill();

            // Crushing Border
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;

            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const hx = size * Math.cos(angle);
                const hy = size * Math.sin(angle) * ISO_SCALE_Y;
                if (i===0) ctx.moveTo(hx,hy); else ctx.lineTo(hx,hy);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (visual === 'FIREBALL' || visual === 'EXPLOSION') {
            // --- BURNING GROUND ---
            // Magma pulsing
            const heat = Math.sin(time * 5 + x * 0.1) * 0.5 + 0.5;

            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = `rgba(50, 10, 10, 0.6)`; // Charred ground
            traceFn();
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = color;
            ctx.globalAlpha = heat * 0.4;
            traceFn();
            ctx.fill();

            // Rising Embers (Deterministic per tile)
            const seed = Math.abs(x + y);
            const emberY = (time * 50 + seed) % 40;
            const emberAlpha = 1 - (emberY / 40);

            ctx.fillStyle = '#fbbf24';
            ctx.globalAlpha = emberAlpha;
            ctx.beginPath();
            ctx.arc(x + Math.sin(time*2)*5, y - emberY + 10, 2, 0, Math.PI*2);
            ctx.fill();

        } else {
            // --- POISON / FOG / GENERIC ---
            // Breathing Grid
            const breath = 0.3 + 0.15 * Math.sin(time * 2 + dist * 0.5);

            ctx.fillStyle = color;
            ctx.globalAlpha = breath;
            ctx.globalCompositeOperation = 'source-over'; 
            traceFn();
            ctx.fill();

            // Border
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.5;
            ctx.stroke();

            // Rising Bubbles / Particles
            const seed = Math.abs(x * 7 + y * 13); 
            const count = (seed % 3) + 1;

            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = color;

            for(let i=0; i<count; i++) {
                const speed = 20 + (seed % 20);
                const offset = (seed * i * 100);
                const bY = (time * speed + offset) % 40; 
                const bAlpha = 1 - (bY / 40); 
                const bX = Math.sin(time * 3 + offset) * 10;

                ctx.globalAlpha = bAlpha * 0.8;
                ctx.beginPath();
                ctx.arc(x + bX, y - bY + 15, 2 + i, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Hex, Skill, Projectile } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

// Lightweight struct to track Zones (Both Instant Casts & Persistent Fields)
interface ZoneSource {
    type: 'CAST' | 'FIELD';
    q: number;
    r: number;
    radius: number; // Hex radius
    radiusSq: number; // For fast distance check (cached)
    color: string;
    visual: string;
    progress: number; // 0-1 for CAST, 1.0 for FIELD
}

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 

export class GridSystem {
    // Cache
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuse buffers
    private _activeZones: ZoneSource[] = [];
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        this.ensureCache(engine);
        const limit = HEX_SIZE * 2; 

        // Find closest tile visual center
        let bestTile: CachedTile | null = null;
        let bestDist = Infinity;

        for (const tile of this._tileCache) {
            const visualY = tile.py - tile.h;
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - visualY);
            if (dist < limit && dist < bestDist) { 
                bestDist = dist;
                bestTile = tile;
            }
        }

        if (bestTile) {
            const testHex = HexUtils.fromPx(wx, wy + bestTile.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === bestTile.q && rounded.r === bestTile.r) {
                return { q: bestTile.q, r: bestTile.r };
            }
        }
        return null;
    }

    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;
            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         if (nHeight > uHeight) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        });
        return occluded;
    }

    submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.ensureCache(engine);

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Reset buffers
        this._activeZones.length = 0;
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        // 1. COLLECT ZONES (Casting & Fields)

        // A. Casting Agents (Telegraphs)
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);

                if (a.stunTimer <= 0 && a.silenceTimer <= 0 && !a.banished && a.castingSkillIdx !== -1) {
                    const s = a.skills[a.castingSkillIdx];
                    if (s && s.type === 'AOE') {
                        let tq = a.q, tr = a.r;
                        if (a.targetHex) { tq = a.targetHex.q; tr = a.targetHex.r; }
                        else if (a.target) { tq = a.target.q; tr = a.target.r; }

                        const progress = 1 - (a.castTimer / s.cast);
                        const radius = (s.aoeRadius || 1);

                        this._activeZones.push({
                            type: 'CAST',
                            q: tq, r: tr,
                            radius: radius,
                            radiusSq: radius + 0.5, 
                            color: s.color,
                            visual: s.visual || 'BOLT',
                            progress: progress
                        });
                    }
                }
            }
        }

        // B. Persistent Fields (Poison, Gravity, etc.)
        for (const f of engine.fields) {
            // Determine Visual Type based on Skill Properties for richer rendering
            let visual = f.visualType; // Default from skill.visual (e.g., FIREBALL, SMOKE)

            // Override for specific logic types to ensure correct ZoneRenderer appearance
            if (f.skill.ccType === 'PULL' || f.skill.name.includes("黑洞") || f.skill.name.includes("事件視界")) {
                visual = 'BLACK_HOLE';
            } else if (f.skill.visual === 'FIREBALL' || f.skill.name.includes("烈焰") || f.skill.name.includes("燃燒")) {
                visual = 'FIREBALL';
            }

            this._activeZones.push({
                type: 'FIELD',
                q: f.q, r: f.r, 
                radius: f.radius,
                radiusSq: f.radius + 0.5,
                color: f.color,
                visual: visual,
                progress: 1.0 // Fields are always "full" active
            });
        }

        // 2. ITERATE TILES
        const PROJ_LIGHT_RADIUS_SQ = 1600; // 40^2

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualY = py + offset;

            if (visualY > py + 800) continue;

            const k = `${q},${r}`;

            // --- SUBMIT OBSTACLE ---
            const obstacleType = engine.obstacles.get(k);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = visualY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualY - h - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // --- SUBMIT TERRAIN ---

            let zoneInfo = undefined;

            // Iterate zones to find overlap
            // Use simple distance check to include all tiles in range
            for (const zone of this._activeZones) {
                const dist = (Math.abs(q - zone.q) + Math.abs(q + r - zone.q - zone.r) + Math.abs(r - zone.r)) / 2;

                if (dist <= zone.radius) {
                    zoneInfo = {
                        type: zone.type,
                        color: zone.color,
                        visual: zone.visual,
                        progress: zone.progress,
                        centerQ: zone.q, 
                        centerR: zone.r, 
                        radius: zone.radius,
                        dist: dist 
                    };
                    // Priority: Field overwrites Cast (usually looks better)
                    if (zone.type === 'FIELD') break; 
                }
            }

            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const bonus = Math.max(0, Math.floor((agentH - h) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;
                const dist = (Math.abs(q - highlightAgent.q) + Math.abs(q + r - highlightAgent.q - highlightAgent.r) + Math.abs(r - highlightAgent.r)) / 2;

                if (dist <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = visualY; 
            op.z = 0;

            op.tx = px; 
            op.ty = visualY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q;
            op.tr = r;

            // Overlays
            op.oStatus = specialStatus;
            op.oDanger = zoneInfo; 
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange;
            op.oRangeCol = rangeColor;
            op.oHover = isHover;
            op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator, drawUltimateGroundCircle, drawUltimateChantVFX } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Ground Y (The floor)
            const visualY = agent.py - h;

            const op = renderList.next();
            op.type = RenderOpType.UNIT;
            op.y = agent.py + 1; // Sort base
            op.z = 10;

            op.agent = agent;
            op.tx = agent.px; // Draw X
            op.ty = visualY;  // Draw Y (Ground)
            op.time = globalTime;
            op.uSelected = (highlightAgent === agent);
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }
        const visualY = agent.py - h;
        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =========================================================================================
    // 🎨 ASSEMBLY PIPELINE: The core drawing logic
    // =========================================================================================
    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Calculate Scaling
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }
        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        // START MAIN TRANSFORM STACK
        ctx.save();

        // 2. Global Position Transform (Screen Space -> Unit Root)
        ctx.translate(drawX, drawY); 
        ctx.scale(scaleFactor, scaleFactor);

        // Calculate Physics Offsets (Scaled to Local Space)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // 3. LAYER: GROUND (Shadows / Base Plates / Casting Circles)
        // These are drawn relative to physics X/Y but usually stay on ground (Z=0)
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            this.drawGroundElements(ctx, agent, physX, physY, physZ, globalTime);
