        // Visual centering correction to align with the visual center of the isometric base
        ctx.translate(0, -12); 

        // Slight hover animation to emphasize 3D nature
        const iconFloat = Math.sin(t * 3) * 2;
        ctx.translate(0, iconFloat);

        ctx.globalAlpha = 0.9;
        ctx.drawImage(assets.icon, -32, -32, 64, 64);
        ctx.restore();

        ctx.restore();

        // Flying Tether
        if (agent.movementType === MovementType.FLYING) {
            drawFlyingAnchor(ctx, agent, t, px, py, pz);
        }

        // Casting Magic Circle
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
