import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.3 - (p.z / 400)); // Lighter shadow
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'SPARK') {
            // ✨ KINETIC SPARKS (Light Streaks)
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
            const stretch = Math.min(4.0, 1.0 + speed / 150); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.6); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = Math.pow(1 - progress, 2); 

            // Streamlined Shape
            const grad = ctx.createLinearGradient(-p.size, 0, p.size, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.2, p.color);
            grad.addColorStop(0.8, '#fff'); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.5, 0, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            // ☁️ VOLUMETRIC SMOKE
            const scale = 0.5 + progress * 2.0; 
            const alpha = (1 - progress) * 0.6; 

            ctx.scale(scale, scale);
            ctx.rotate(p.rotation + progress * 0.5); 
            ctx.globalAlpha = alpha;

            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
            grad.addColorStop(0, p.color);
            grad.addColorStop(1, 'rgba(0,0,0,0)'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.arc(p.size*0.5, p.size*0.5, p.size*0.6, 0, Math.PI*2);
            ctx.arc(-p.size*0.4, -p.size*0.3, p.size*0.7, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'RING') {
            // 🌊 ENERGY RIPPLE
            ctx.scale(1, 0.55); 
            const r = progress * p.size * 2; 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 4;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

            if (progress > 0.2) {
                ctx.lineWidth = (1 - progress) * 2;
                ctx.globalAlpha = (1 - progress) * 0.5;
                ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); ctx.stroke();
            }

        } else if (p.type === 'BLAST') {
            // 💥 SPIKED EXPLOSION
            ctx.scale(1, 0.55); 
            const r = p.size * (progress); 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 6; 
            ctx.globalAlpha = (1 - progress);

            ctx.beginPath(); 
            const spikes = 12;
            for(let i=0; i<=spikes; i++) {
                const angle = (i/spikes) * Math.PI*2;
                const rad = r * (1.0 + (i%2===0 ? 0.2 : 0)); 
                const px = Math.cos(angle) * rad;
                const py = Math.sin(angle) * rad;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'CHIP') {
            // 💎 MATERIAL
            ctx.rotate(p.rotation);

            const grad = ctx.createLinearGradient(-p.size, -p.size, p.size, p.size);
            grad.addColorStop(0, '#ffffff'); 
            grad.addColorStop(0.3, p.color);
            grad.addColorStop(1, '#000000'); 

            ctx.fillStyle = grad;
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;

            if (p.type === 'CHIP') {
                ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
            } else {
                ctx.beginPath();
                ctx.moveTo(-p.size, -p.size/2); 
                ctx.lineTo(p.size * 0.8, -p.size * 0.2); 
                ctx.lineTo(0, p.size); 
                ctx.lineTo(-p.size * 0.5, p.size * 0.5);
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); 
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.9;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.max(0, 1 - Math.pow(progress, 3)); 
                ctx.globalAlpha = alpha;
                ctx.rotate(p.rotation + progress * 5);
                const perspective = 1.0 + (p.z * 0.002);
                const scale = (p.size / 64) * perspective * (1 - progress * 0.5); 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'DEATH_RAY') {
            this.drawDeathRay(ctx, p, progress);
        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawDomainArea(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter';

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        const beamWidth = 6 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(2, beamWidth * 0.5);
        ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Glow
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2.5; 
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Helix
        const freq = 0.12; 
        const amp = 8 * (1 - progress); 
        const phase = Date.now() * 0.025; 

        ctx.lineWidth = 2; 
        ctx.globalAlpha = 0.9 * (1 - progress);
        ctx.strokeStyle = p.color; 

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase + Math.PI) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // Flares
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1 - progress;
        ctx.beginPath(); ctx.arc(0, 0, beamWidth * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(dist, 0, beamWidth * 2.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // ☠️ DEATH RAY (High Velocity Particle Beam)
    drawDeathRay(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        const alpha = Math.pow(1 - progress, 2);

        // 1. Dark Void Core (Source-Over to block light)
        ctx.globalCompositeOperation = 'source-over'; 
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 4 * alpha;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

        // 2. Intense Crimson Glow (Lighter)
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = p.color; 
        ctx.lineWidth = 12 * alpha;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 20;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
        ctx.shadowBlur = 0;

        // 3. White Hot Needle Center
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2 * alpha;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

        // 4. Chaotic Crackles
        ctx.strokeStyle = '#fca5a5'; 
        ctx.lineWidth = 2 * alpha;
        ctx.beginPath();
        let cx = 0;
        ctx.moveTo(0, 0);
        const segmentLen = 40;
        const steps = Math.ceil(dist / segmentLen);
        for(let i=0; i<steps; i++) {
            cx += segmentLen;
            const cy = (Math.random() - 0.5) * 20 * alpha;
            ctx.lineTo(cx, cy);
        }
        ctx.lineTo(dist, 0);
        ctx.stroke();

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; 
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); 
        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);
            drawHex();
            ctx.clip();
            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();
            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;
            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();
        } else {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHex();
            ctx.stroke();
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHex();
            ctx.stroke();
            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR 4.0: THIN SHAFT (Clean Edition)
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;

        let alpha = 0;
        if (lifeRatio > 0.8) alpha = (1 - lifeRatio) * 5; 
        else if (lifeRatio < 0.3) alpha = lifeRatio * 3.3; 
        else alpha = 1.0;

        const height = 800; 
        const width = p.size; // Strictly respects spawn size (18)

        // --- 1. THE BEAM CORE ---
        ctx.save();
        // Use source-over to prevent additive blowout when multiple beams overlap
        ctx.globalCompositeOperation = 'source-over'; 

        const beamGrad = ctx.createLinearGradient(-width, 0, width, 0);
        beamGrad.addColorStop(0, 'rgba(255,255,255,0)');
        beamGrad.addColorStop(0.2, p.color);
        beamGrad.addColorStop(0.5, 'rgba(255,255,255,0.6)'); 
        beamGrad.addColorStop(0.8, p.color);
        beamGrad.addColorStop(1, 'rgba(255,255,255,0)');

        // Vertical fade
        const vGrad = ctx.createLinearGradient(0, 0, 0, -height);
        vGrad.addColorStop(0, 'rgba(255,255,255,1)');
        vGrad.addColorStop(0.8, 'rgba(255,255,255,0.5)');
        vGrad.addColorStop(1, 'rgba(255,255,255,0)');

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.7; 
        ctx.fillRect(-width, -height, width * 2, height);

        // --- 2. GROUND RIPPLE (Impact Ring) ---
        ctx.save();
        ctx.scale(1, 0.58); 

        // Ground glow is okay to be Screen
        ctx.globalCompositeOperation = 'screen';
        const ringSize = width * 1.5 * (0.5 + (1-lifeRatio)); 

        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha * 0.9;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.stroke();

        // Center spot
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = alpha * 0.6;
        ctx.beginPath(); ctx.arc(0, 0, width * 0.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
        ctx.restore();
    },

    // 🩸 DOMAIN (Active Field Visuals) - NO MORE BLACK HOLE CIRCLES
    drawDomainArea(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;
         const isChaos = isChaosStyle(p.color);

         ctx.save();
         ctx.scale(1, 0.55); 

         if (isChaos) {
             // Chaos: Void Hole (Darkness) -> NOW A VORTEX GRADIENT
             ctx.globalCompositeOperation = 'source-over'; 
             const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
             voidGrad.addColorStop(0, 'rgba(0,0,0,0.9)'); 
             voidGrad.addColorStop(0.6, 'rgba(0,0,0,0.8)');
             voidGrad.addColorStop(0.8, p.color); 
             voidGrad.addColorStop(1, 'transparent');

             ctx.fillStyle = voidGrad;
             ctx.globalAlpha = alpha * 0.8; 
             ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
         } else {
             // Order: Holy Ground (Light Ring) - HEAVIER NOW
             ctx.globalCompositeOperation = 'screen'; // Light adds up

             // 1. Base Glow (Soft Gradient)
             const lightGrad = ctx.createRadialGradient(0, 0, r * 0.6, 0, 0, r);
             lightGrad.addColorStop(0, 'rgba(0,0,0,0)'); // Transparent center
             lightGrad.addColorStop(0.8, p.color); // Glowing rim
             lightGrad.addColorStop(1, 'transparent');

             ctx.fillStyle = lightGrad;
             ctx.globalAlpha = alpha * 0.6; 
             ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

             // 2. Heavy Ring (The Boundary)
             ctx.strokeStyle = p.color;
             ctx.lineWidth = 4;
             ctx.globalAlpha = alpha;
             ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();

             // 3. Inner decorative ring
             ctx.strokeStyle = '#fff';
             ctx.lineWidth = 1;
             ctx.setLineDash([10, 10]);
             ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); ctx.stroke();
         }

         // Cracks / Runes (Rotating)
         ctx.strokeStyle = p.color; 
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();
         ctx.restore();

         // Rising Energy (The Cylinder effect)
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;
         ctx.beginPath();
         ctx.moveTo(-r/2, 0); ctx.lineTo(-r/4, -300); ctx.lineTo(r/4, -300); ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        const r = progress * p.size; // Expands to max size
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Hex, Skill, Projectile } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

// Lightweight struct to track Zones (Both Instant Casts & Persistent Fields)
interface ZoneSource {
    type: 'CAST' | 'FIELD';
    q: number;
    r: number;
    radius: number; // Hex radius
    radiusSq: number; // For fast distance check (cached)
    color: string;
    visual: string;
    progress: number; // 0-1 for CAST, 1.0 for FIELD
}

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 

export class GridSystem {
    // Cache
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuse buffers
    private _activeZones: ZoneSource[] = [];
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        this.ensureCache(engine);
        const limit = HEX_SIZE * 2; 

        // Find closest tile visual center
        let bestTile: CachedTile | null = null;
        let bestDist = Infinity;

        for (const tile of this._tileCache) {
            const visualY = tile.py - tile.h;
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - visualY);
            if (dist < limit && dist < bestDist) { 
                bestDist = dist;
                bestTile = tile;
            }
        }

        if (bestTile) {
            const testHex = HexUtils.fromPx(wx, wy + bestTile.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === bestTile.q && rounded.r === bestTile.r) {
                return { q: bestTile.q, r: bestTile.r };
            }
        }
        return null;
    }

    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;
            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         if (nHeight > uHeight) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        });
        return occluded;
    }

    submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.ensureCache(engine);

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Reset buffers
        this._activeZones.length = 0;
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        // 1. COLLECT ZONES (Casting & Fields)

        // A. Casting Agents (Telegraphs)
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);

                if (a.stunTimer <= 0 && a.silenceTimer <= 0 && !a.banished && a.castingSkillIdx !== -1) {
                    const s = a.skills[a.castingSkillIdx];
                    if (s && s.type === 'AOE') {
                        let tq = a.q, tr = a.r;
                        if (a.targetHex) { tq = a.targetHex.q; tr = a.targetHex.r; }
                        else if (a.target) { tq = a.target.q; tr = a.target.r; }

                        const progress = 1 - (a.castTimer / s.cast);
                        const radius = (s.aoeRadius || 1);

                        this._activeZones.push({
                            type: 'CAST',
                            q: tq, r: tr,
                            radius: radius,
                            radiusSq: radius + 0.5, 
                            color: s.color,
                            visual: s.visual || 'BOLT',
                            progress: progress
                        });
                    }
                }
            }
        }

        // B. Persistent Fields (Poison, Gravity, etc.)
        for (const f of engine.fields) {
            // Determine Visual Type based on Skill Properties for richer rendering
            let visual = f.visualType; // Default from skill.visual (e.g., FIREBALL, SMOKE)

            // Override for specific logic types to ensure correct ZoneRenderer appearance
            if (f.skill.ccType === 'PULL' || f.skill.name.includes("黑洞") || f.skill.name.includes("事件視界")) {
                visual = 'BLACK_HOLE';
            } else if (f.skill.visual === 'FIREBALL' || f.skill.name.includes("烈焰") || f.skill.name.includes("燃燒")) {
                visual = 'FIREBALL';
            }

            this._activeZones.push({
                type: 'FIELD',
                q: f.q, r: f.r, 
                radius: f.radius,
                radiusSq: f.radius + 0.5,
                color: f.color,
                visual: visual,
                progress: 1.0 // Fields are always "full" active
            });
        }

        // 2. ITERATE TILES
        const PROJ_LIGHT_RADIUS_SQ = 1600; // 40^2

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualY = py + offset;

            if (visualY > py + 800) continue;

            const k = `${q},${r}`;

            // --- SUBMIT OBSTACLE ---
            const obstacleType = engine.obstacles.get(k);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = visualY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualY - h - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // --- SUBMIT TERRAIN ---

            let zoneInfo = undefined;

            // Iterate zones to find overlap
            // Use simple distance check to include all tiles in range
            for (const zone of this._activeZones) {
                const dist = (Math.abs(q - zone.q) + Math.abs(q + r - zone.q - zone.r) + Math.abs(r - zone.r)) / 2;

                if (dist <= zone.radius) {
                    zoneInfo = {
                        type: zone.type,
                        color: zone.color,
                        visual: zone.visual,
                        progress: zone.progress,
                        centerQ: zone.q, 
                        centerR: zone.r, 
                        radius: zone.radius,
                        dist: dist 
                    };
                    // Priority: Field overwrites Cast (usually looks better)
                    if (zone.type === 'FIELD') break; 
                }
            }

            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const bonus = Math.max(0, Math.floor((agentH - h) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;
                const dist = (Math.abs(q - highlightAgent.q) + Math.abs(q + r - highlightAgent.q - highlightAgent.r) + Math.abs(r - highlightAgent.r)) / 2;

                if (dist <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            // UX UPDATE: Only show unit footprint indicators when NOT running (Planning phase)
            // When battle starts, remove the clutter.
            const hasUnit = !engine.isRunning && this._unitPresence.has(k);

            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = visualY; 
            op.z = 0;

            op.tx = px; 
            op.ty = visualY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q;
            op.tr = r;

            // Overlays
            op.oStatus = specialStatus;
            op.oDanger = zoneInfo; 
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange;
            op.oRangeCol = rangeColor;
            op.oHover = isHover;
            op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";
import { HEX_SIZE } from "../../../constants";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    // We are at Ground Level (0,0) in the scaled context.
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    // Rotating Rune Ring - Clear indication of ground position
    ctx.save();
    ctx.scale(1, 0.58); // Isometric flat on ground
    // Use lineDashOffset to simulate rotation without distorting the ellipse
    ctx.lineDashOffset = -t * 20;

    // Outer dashed ring
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    // Only visible if unit is airborne to show connection
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); // Fade out near unit feet

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        // Draw Main Tether Line
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        // Draw Moving Energy Pulses up the tether
        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; // 0 to 1, faster speed
            const px = feetX * p;
            const py = feetY * p;

            // Draw small horizontal dash/disk traveling up
            // Scale based on height to simulate perspective
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); // Faster spin for thrusters

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    // 3 Arcs for stability look
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; // Flicker
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    if (skill.tag === 'ULT') {
        drawUltimateChantVFX(ctx, agent, t);
        return;
    }

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

// 🌀 ULTIMATE BODY GLOW (Intense Core Accumulation)
export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    // Intense Core Glow (Chest)
    // Pulsing increases speed as cast finishes
    const pulseSpeed = 10 + progress * 20; 
    const pulse = 1 + Math.sin(t * pulseSpeed) * (0.1 + progress * 0.2);

    // Outer Aura
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3 * progress;
    ctx.beginPath();
    ctx.arc(0, -40, 45 * pulse, 0, Math.PI*2);
    ctx.fill();

    // Inner Core
    ctx.globalAlpha = 0.6 * progress;
    ctx.beginPath();
    ctx.arc(0, -40, 25 * pulse, 0, Math.PI*2);
    ctx.fill();

    // White Hot Center (Critical Mass)
    ctx.fillStyle = '#fff';
    ctx.globalAlpha = 0.8 * progress * progress; // Quadratic ramp up
    ctx.beginPath();
    ctx.arc(0, -40, 10 * pulse, 0, Math.PI*2);
    ctx.fill();

    // Rising Particles (Spirit Bomb style)
    if (progress > 0.2) {
        const pCount = 5;
        for(let i=0; i<pCount; i++) {
            const angle = (t * 5 + i) % (Math.PI*2);
            const dist = 60 * (1 - ((t + i*0.2) % 1)); // Suck INWARD
            const px = Math.cos(angle) * dist;
            const py = -40 + Math.sin(angle) * dist;

            ctx.fillStyle = color;
            ctx.globalAlpha = 0.5 * progress;
            ctx.beginPath(); ctx.arc(px, py, 2, 0, Math.PI*2); ctx.fill();
        }
    }

    ctx.restore();
}

// 🌀 ULTIMATE DOMAIN EXPANSION (The "Cathedral" Effect)
// REPLACED PIE CHART WITH VOLUMETRIC LIGHT & RUNIC ARRAYS
export function drawUltimateGroundCircle(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, t: number, progress: number, skillRadius: number = 1, isAOE: boolean) {
    ctx.save();
    ctx.translate(x, y);
    ctx.globalCompositeOperation = 'lighter'; // Additive blending for holograms

    // --- EXPANSION LOGIC ---
    const targetPx = isAOE ? (skillRadius * HEX_SIZE) : (HEX_SIZE * 1.5);
    const ease = 1 - Math.pow(1 - progress, 4); // Fast expand
    const r = targetPx * ease;

    // --- 1. VOLUMETRIC CYLINDER (The "Presence" Zone) ---
    // A rising curtain of light that gives the area 3D volume
    if (r > 10) {
        ctx.save();
        const beamH = 400; // Height of the light
        // Gradients are relative to current transform
        const beamGrad = ctx.createLinearGradient(0, 0, 0, -beamH);
        beamGrad.addColorStop(0, color); 
        beamGrad.addColorStop(0.3, 'rgba(0,0,0,0)'); // Fade fast vertically

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = 0.15 * progress + (Math.sin(t * 10) * 0.05); // Pulsing

        // Draw approximate cylinder via squashed rect (billboard-ish approach)
        // Since we are in an isometric context, drawing "up" creates a wall
        const w = r * 2;
        ctx.fillRect(-r, -beamH, w, beamH);
        ctx.restore();
    }

    // --- 2. GROUND GEOMETRY (The Rune) ---
    ctx.save();
    ctx.scale(1, 0.58); // Isometric Flatten

    // A. Outer Heavy Ring (Thick)
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.lineWidth = 4;
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.8 * progress;
    ctx.shadowColor = color;
    ctx.shadowBlur = 10;
    ctx.stroke();
    ctx.shadowBlur = 0; // Reset expensive shadow

    // B. Inner Rotating Geometric (Octagram - 8 Point Star)
    if (r > 20) {
        ctx.save();
        ctx.rotate(t * 0.5); // Slow majestic rotation

        ctx.beginPath();
        const points = 8;
        const innerR = r * 0.85;

        // Draw Star Pattern (Connecting vertices)
        for(let i=0; i<=points; i++) {
            const angle = i * (Math.PI * 2 / points);
            // Vertex
            ctx.lineTo(Math.cos(angle) * innerR, Math.sin(angle) * innerR);
            // Inner Vertex (Star indent)
            const nextAngle = angle + (Math.PI / points);
            ctx.lineTo(Math.cos(nextAngle) * (innerR * 0.5), Math.sin(nextAngle) * (innerR * 0.5));
        }
        ctx.closePath();

        ctx.lineWidth = 2;
        ctx.strokeStyle = '#fff'; // White hot center lines
        ctx.globalAlpha = 0.5 * progress;
        ctx.stroke();

        // Faint Fill inside the star
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.1 * progress;
        ctx.fill();

        ctx.restore();
    }

    // C. Center Beam Source (The "Eye")
    const centerPulse = 1 + Math.sin(t * 20) * 0.2;
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.1 * centerPulse, 0, Math.PI*2);
    ctx.fillStyle = '#fff';
    ctx.globalAlpha = 0.8 * progress;
    ctx.fill();

    // D. Orbiting Runes (Dashed Ring)
    ctx.beginPath();
    ctx.arc(0, 0, r * 1.1, 0, Math.PI*2);
    ctx.lineWidth = 1;
    ctx.setLineDash([10, 20]); // Long dashes
    ctx.lineDashOffset = -t * 30; // Rotate opposite
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.6 * progress;
    ctx.stroke();

    ctx.restore(); // End Ground Geometry

    // --- 3. VERTICAL PILLAR (The Beacon) ---
    // A thin, intense beam right in the center reaching the sky
    if (progress > 0.1) {
        const coreW = Math.min(30, r * 0.3);
        const coreH = 1000; // To the sky

        const coreGrad = ctx.createLinearGradient(0, 0, 0, -coreH);
        coreGrad.addColorStop(0, '#fff'); // White base
        coreGrad.addColorStop(0.1, color); 
        coreGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = 0.4 * progress; 
        ctx.fillRect(-coreW/2, -coreH, coreW, coreH);
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; 

    // 1. FROZEN - ICE PRISM (Encasing the unit)
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); // Center of body

        // Draw Hexagonal Prism
        const w = 30;
        const h = 50;

        ctx.globalCompositeOperation = 'source-over';
        // Back Faces
        ctx.fillStyle = 'rgba(186, 230, 253, 0.4)'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(w, -h); ctx.lineTo(w, h); ctx.lineTo(-w, h);
        ctx.fill();

        // Front Faces (Glassy)
        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.6)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
        grad.addColorStop(1, 'rgba(14, 165, 233, 0.5)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(0, -h - 10); // Top Tip
        ctx.lineTo(w + 5, -h + 10);
        ctx.lineTo(w, h);
        ctx.lineTo(0, h + 10); // Bottom Tip
        ctx.lineTo(-w, h);
        ctx.lineTo(-w - 5, -h + 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Glint
        ctx.globalCompositeOperation = 'lighter';
        ctx.beginPath();
        ctx.moveTo(0, -h-10); ctx.lineTo(0, h+10);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH - GHOSTLY CAGE (Rotates around unit)
    // MUTUALLY EXCLUSIVE: Only draw if NOT Poly'd and NOT Stasis
    if (agent.banished && agent.visualStatus !== 'POLYMORPH' && agent.visualStatus !== 'STASIS') {
        ctx.translate(0, -30); // Body center

        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        // Vertical Bars orbiting (Simulated 3D Cylinder)
        const bars = 5;
        const radius = 25;
        const height = 50;

        for(let i=0; i<bars; i++) {
            // Rotate bars over time
            const angle = t * 2 + (i / bars) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle); // Depth

            // Perspective scale
            // const scale = 1 + z * 0.1;
            const alpha = 0.5 + (z + 1) * 0.25; // Fade back bars

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(x, -height);
            ctx.lineTo(x, height);
            ctx.stroke();

            // Runes on bars
            if (i % 2 === 0) {
                ctx.fillStyle = '#d8b4fe';
                ctx.beginPath(); ctx.arc(x, -height/2 + Math.sin(t*3+i)*10, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        // Top and Bottom Rings
        ctx.globalAlpha = 0.6;
        ctx.save();
        ctx.scale(1, 0.3); // Isometric
        ctx.beginPath(); ctx.arc(0, -height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. STUN - 3D DIZZY RING
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y - 10);

        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 3;

        const count = 5;
        const radius = 25;

        // Orbiting Stars
        for(let i=0; i<count; i++) {
            const angle = t * 4 + (i / count) * Math.PI * 2;
            // 3D Orbit: Y is squashed
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius * 0.3;
            // Z-sort simulation: if sin(angle) > 0, it's in front
            const scale = 1 + Math.sin(angle) * 0.3;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.fillStyle = '#facc15';
            // OPTIMIZATION: Removed shadowBlur. Added fake glow circle.
            ctx.beginPath();
            const starPts = 5;
            for(let j=0; j<starPts*2; j++) {
                const r = j%2===0 ? 6 : 2;
                const a = j * Math.PI / starPts;
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            }
            ctx.fill();

            // Fake Glow
            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();

            ctx.restore();
        }
    }

    // 4. SILENCE - FLOATING RUNE SEAL
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 15);

        const scale = 1 + Math.sin(t * 5) * 0.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';

        // OPTIMIZATION: Fake glow via multi-pass stroke instead of shadowBlur
        ctx.globalCompositeOperation = 'lighter';

        const drawRune = (width: number, alpha: number) => {
            ctx.lineWidth = width;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.rect(-15, -10, 30, 20);
            ctx.fill();
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(-8, -5); ctx.lineTo(8, 5);
            ctx.moveTo(8, -5); ctx.lineTo(-8, 5);
            ctx.stroke();
        };

        drawRune(4, 0.3); // Glow pass
        drawRune(2, 1.0); // Core pass
    }

    // 5. DoT - Rising Bubbles / Smoke
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; 
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT - Spiraling +
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;

        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; // Flattened

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

